template:
use std::cell::Cell;

type NameCell = Cell<String>;

fn swap_names(
    a: &NameCell,
    b: &NameCell,
) {
    a.⟦slot1⟧(⟦slot2⟧);
}

fn main() {
    let n1 = Cell::new("A".into());
    let n2 = Cell::new("B".into());
    swap_names(&n1, &n2);
    println!("{}, {}",
        n1.take(), n2.take());
}

tests:
#[test]
fn swaps_strings() {
    let a = Cell::new(String::from("hello"));
    let b = Cell::new(String::from("world"));
    swap_names(&a, &b);
    assert_eq!(a.take(), "world");
    assert_eq!(b.take(), "hello");
}
